SELECT 'xcheck|' || count(*) || ' complete+seladd_true+score_ge60' FROM articles a JOIN publications p ON p.article_id = a.id WHERE a.grouping_status = 'complete' AND a.selection_adds_value = true AND p.score >= 60;
SELECT 'xcheck_t1|' || count(*) || ' eligible_t1_score_ge60' FROM articles a JOIN publications p ON p.article_id = a.id JOIN sources s ON s.id = a.source_id WHERE a.grouping_status = 'complete' AND a.selection_adds_value = true AND p.score >= 60 AND s.tier = 'T1';
SELECT 'top_complete|' || a.id || '|score=' || p.score || '|tier=' || s.tier || '|gstat=' || a.grouping_status || '|sav=' || coalesce(a.selection_adds_value::text,'null') || '|sel=' || p.selected || '|bf=' || a.backfill || '|bfreason=' || coalesce(a.backfill_reason,'null') FROM articles a JOIN publications p ON p.article_id = a.id JOIN sources s ON s.id = a.source_id WHERE p.score >= 65 ORDER BY p.score DESC LIMIT 12;
